function M.to_pascal(name)
  local r = name:gsub("_(%a)", function(l)
    return l:upper()
  end)
  return r:sub(1, 1):upper() .. r:sub(2)
end

function M.register_collection(coll)
  local wk = get_wk()
  if not wk or type(coll.keys) ~= "table" then return end

  local spec = {}
  if coll.keys.files then
    spec[#spec + 1] = { coll.keys.files, desc = "Pickers[" .. coll.name .. "]: files" }
  end
  if coll.keys.grep then
    spec[#spec + 1] = { coll.keys.grep, desc = "Pickers[" .. coll.name .. "]: grep" }
  end
  if coll.keys.smart then
    spec[#spec + 1] = { coll.keys.smart, desc = "Pickers[" .. coll.name .. "]: smart" }
  end

  if #spec > 0 then pcall(wk.add, spec) end
end

function M.engine_module(engine_name)
  return ENGINE_MODULE[engine_name]
end

function M.dispatch(action, source, engine_mod)
  dispatch_action(action, source, engine_mod)
end

local function action_arg()
  return { name = "action", type = "STRING", values = ACTION_VALUES, optional = true }
end

local function find_all_arg()
  return { name = "all", type = "STRING", values = { "all" }, optional = true }
end

local function scope_route(scope)
  return {
    path = { scope },
    args = { action_arg(), find_all_arg() },
    desc = "Scope: " .. scope,
    run = function(ctx)
      require("pickers.command").handle({ fargs = { scope, ctx.pos[1], ctx.pos[2] } })
    end,
  }
end

local function dir_route()
  return {
    path = { "dir" },
    args = { { name = "nav", type = "PICKERS_DIR_NAV", optional = true }, action_arg() },
    desc = "Directory navigation (depth / alias / explicit path)",
    run = function(ctx)
      require("pickers.command").handle({ fargs = { "dir", ctx.pos[1], ctx.pos[2] } })
    end,
  }
end

local function builtin_route()
  return {
    path = { "builtin" },
    args = { { name = "name", type = "PICKERS_BUILTIN_NAME" } },
    desc = "Native picker (git/lsp/search/…) — see docs/BUILTINS.md",
    run = function(ctx)
      require("pickers.builtins").run(ctx.pos[1])
    end,
  }
end

local function collection_route(name)
  return {
    path = { name },
    args = { action_arg(), find_all_arg() },
    desc = "User-defined collection: " .. name,
    run = function(ctx)
      require("pickers.command").handle({ fargs = { name, ctx.pos[1], ctx.pos[2] } })
    end,
  }
end

function M.pick_files(opts)
  local ok, Picker = pcall(require, "snacks.picker")
  if not ok then
    notify.error("snacks.picker unavailable")
    return
  end

  -- Custom find command (system source) — bypass the "files" source's own
  -- cmd-selection entirely via a custom finder, same proc() builder snacks'
  -- own files.lua uses internally.
  if opts.find_command then
    safe_call(Picker.pick, {
      source = "files",
      title = opts.prompt,
      finder = function(_, ctx)
        return require("snacks.picker.source.proc").proc(
          ctx:opts({
            cmd = opts.find_command[1],
            args = vim.list_slice(opts.find_command, 2),
            ---@param item snacks.picker.finder.Item
            transform = function(item)
              item.cwd = opts.roots[1]
              item.file = item.text
            end,
          }),
          ctx
        )
      end,
    })
    return
  end

  local f = opts.find or {}
  local call_opts = {
    title = opts.prompt,
    hidden = f.hidden,
    ignored = f.no_ignore,
    follow = f.follow,
    exclude = f.exclude,
  }

function M.pick_item(opts)
  local ok, Picker = pcall(require, "snacks.picker")
  if not ok then
    notify.error("snacks.picker unavailable")
    return
  end

  Picker.select(opts.items, {
    prompt = opts.prompt,
    format_item = function(item)
      return (type(item) == "table") and item.text or tostring(item)
    end,
  }, function(item)
    if item then opts.on_select(item) end
  end)
end

function M.live_grep(opts)
  local ok, builtin = pcall(require, "telescope.builtin")
  if not ok then
    notify.error("telescope.builtin unavailable")
    return
  end

  local extra = opts.additional_args or {}
  local exclude = (opts.find or {}).exclude or {}
  safe_call(builtin.live_grep, {
    prompt_title = opts.prompt,
    search_dirs = opts.roots,
    default_text = opts.query,
    additional_args = function()
      local args = { "--hidden", "--no-ignore-vcs", "-S" }
      for _, g in ipairs(exclude) do
        args[#args + 1] = "-g"
        args[#args + 1] = "!" .. g
      end
      return vim.list_extend(args, extra)
    end,
    attach_mappings = require("pickers.result_count").wrap_attach_mappings(nil),
    history = history_opts(),
    path_display = path_display_opts(),
  })
end

function M.smart(opts)
  local ok, finders = pcall(require, "telescope.finders")
  local ok2, pickers = pcall(require, "telescope.pickers")
  local ok3, sorters = pcall(require, "telescope.sorters")
  local ok4, conf = pcall(require, "telescope.config")
  if not (ok and ok2 and ok3 and ok4) then
    notify.error("telescope modules unavailable")
    return
  end

  pickers
    .new({}, {
      prompt_title = opts.prompt or "Smart",
      finder = finders.new_dynamic({
        fn = function(prompt)
          return require("pickers.smart").query(prompt or "", {
            roots = opts.roots,
            find = opts.find,
            additional_args = opts.additional_args,
          })
        end,
        ---@param it Pickers.Smart.Item
        entry_maker = function(it)
          return {
            value = it,
            display = it.display,
            ordinal = it.display,
            filename = it.abspath,
            lnum = it.lnum,
            col = it.col,
          }
        end,
      }),
      sorter = sorters.empty(),
      previewer = conf.values.grep_previewer({}),
      attach_mappings = require("pickers.result_count").wrap_attach_mappings(nil),
      history = history_opts(),
    })
    :find()
end

function M.get_actions()
  if require("pickers.config").get().keys.enable == false then return {} end

  return {
    ["ctrl-a"] = do_create_file,
    ["ctrl-o"] = do_open_background,
    ["shift-enter"] = do_open_background,
  }
end

function M.get_actions()
  if require("pickers.config").get().keys.enable == false then return {} end

  return {
    create_file = do_create_file,
    open_background = do_open_background,
  }
end

function M.telescope_opts(cfg)
  return {
    path = M.dir(cfg) .. "/telescope.txt",
    limit = cfg.history.limit,
  }
end

function M.fzf_path(cfg, kind)
  return M.dir(cfg) .. "/fzf_" .. kind .. ".txt"
end

function M.fzf_opts(cfg)
  return { ["--history"] = M.dir(cfg) .. "/fzf_global.txt" }
end

function M.patch(cfg)
  vim.schedule(function()
    pcall(function()
      require("telescope").setup({ defaults = { history = M.telescope_opts(cfg) } })
    end)
  end)

  if cfg.history.fzf_scope == "patch" then
    vim.schedule(function()
      pcall(function()
        require("fzf-lua").setup({ fzf_opts = M.fzf_opts(cfg) }, true)
      end)
    end)
  end
end

function M.resolve(cfg)
  cfg = cfg or require("pickers.config").get()
  local kc = cfg.keys or {}
  if kc.enable == false then return {} end

  local out = {}
  for _, name in ipairs(M.ORDER) do
    local spec = M.ACTIONS[name]
    local raw = kc[name]
    if raw == nil then raw = spec.default end
    out[name] = { lhs = to_lhs_list(raw), modes = spec.modes }
  end
  return out
end

function M.snacks_win(cfg)
  return require("pickers.keys.adapters.snacks").win(M.resolve(cfg))
end

function M.telescope_mappings(cfg)
  return require("pickers.keys.adapters.telescope").mappings(M.resolve(cfg))
end

function M.fzf_keymap(cfg)
  return require("pickers.keys.adapters.fzf").keymap(M.resolve(cfg))
end

function M.fzf_skipped(cfg)
  return require("pickers.keys.adapters.fzf").skipped(M.resolve(cfg))
end

function M.wrap_attach_mappings(orig)
  local cfg = require("pickers.config").get().result_count
  if not cfg or not cfg.enabled then return orig end

  return function(prompt_bufnr, map)
    if orig then orig(prompt_bufnr, map) end
    return M.attach_mappings(prompt_bufnr)
  end
end

function M.defaults()
  return {
    weights = { filename = 1.0, content = 1.0, both = 25 },
    limit = 2000,
    timeout = 3000,
    frecency = { enabled = false, weight = 1.0, dir = nil },
    dedup_grep_rows = false,
  }
end

function M.config()
  local ok, cfg = pcall(function()
    return require("pickers.config").get()
  end)
  local user = (ok and type(cfg) == "table" and cfg.smart) or {}
  return vim.tbl_deep_extend("force", M.defaults(), user)
end

function M.flush(cfg)
  if dirty then save(cfg) end
end

function M.list_subdirs(dir, prefix, only_git)
  return list_subdirs(dir, prefix, only_git)
end

function M.new(kind, message)
  return { kind = kind, message = message }
end

function M.tostring(err)
  return ("[%s] %s"):format(err.kind or "Error", err.message or "")
end

function M.safe_call(kind, fn, ...)
  local ok, res = pcall(fn, ...)
  if ok then return { ok = true, result = res, err = nil } end
  return { ok = false, result = nil, err = M.new(kind, tostring(res)) }
end

function M.set(action, source)
  _last = { action = action, source = source }
end

function M.get()
  return _last
end
